/* audio_tone.c - play a steady tone for the audio-capture test.
 *
 * Uploads a 440 Hz sample to the SPU and keys it on voice 0 for the whole run,
 * so the emulator produces a continuous tone an audio capture can analyze. The
 * sample loops (the ADPCM end block repeats), so it sustains past its own
 * length. This is the sound counterpart of hello_gpu: a known, checkable output.
 *
 * The tone is generated by vagconv at 22050 Hz and played at the matching pitch,
 * so it sounds at 440 Hz. Exits 0 after its loop.
 */

#include "psx.h"

extern const unsigned char psx_atone[];
extern const unsigned      psx_atone_len;

#define TONE_ADDR 0x1010        /* SPU RAM above the reserved low region */
#define FRAMES 120              /* about two seconds at 60 Hz */

int
main(void)
{
    psx_gpu_init();
    psx_irq_init();
    psx_spu_init();

    psx_spu_upload(TONE_ADDR, psx_atone, (uint32_t)psx_atone_len);
    psx_spu_play(0, TONE_ADDR, PSX_SPU_PITCH_22050, 0x3FFF);

    for (int f = 0; f < FRAMES; f++) {
        psx_vsync();
        psx_display_swap();
    }

    psx_spu_stop(0);
    return 0;
}
